// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.componentsimport androidx.compose.animation.AnimatedVisibilityimport androidx.compose.animation.fadeInimport androidx.compose.animation.fadeOutimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.heightimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.layout.widthimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Sendimport androidx.compose.material.icons.filled.AttachFileimport androidx.compose.material.icons.filled.Micimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.state.ConversationItemimport com.roshan.persona.ui.theme.brainLayerColor/** * Conversation list — renders the chat history with user/NOUS messages. * * User messages: right-aligned, surface color, no avatar. * NOUS messages: left-aligned, elevated surface, persona avatar + layer badge. * * Token streaming: when a streaming partial is shown, the text fades in (no scroll jump). * * @param items list of conversation items from UiStateProvider * @param activePersonaId current persona ID (for avatar color) * @param activePersonaName current persona display name * @param streamingPartial when non-null, shows "Atlas is thinking..." indicator * @param modifier layout modifier */@Composablefun ConversationList(    items: List<ConversationItem>,    activePersonaId: String?,    activePersonaName: String,    streamingPartial: String?,    modifier: Modifier = Modifier,) {    LazyColumn(        modifier = modifier.fillMaxWidth(),        verticalArrangement = Arrangement.spacedBy(8.dp),    ) {        items(items) { item ->            ConversationRow(                item = item,                personaId = activePersonaId,                personaName = activePersonaName,            )        }        if (streamingPartial != null) {            item {                StreamingIndicator(                    personaName = activePersonaName,                    partial = streamingPartial,                )            }        }    }}@Composablefun ConversationRow(    item: ConversationItem,    personaId: String?,    personaName: String,) {    if (item.isNous) {        // NOUS message — left aligned with avatar + persona + layer        Row(            modifier = Modifier.fillMaxWidth(),            horizontalArrangement = Arrangement.Start,            verticalAlignment = Alignment.Top,        ) {            PersonaAvatar(                personaId = personaId,                displayName = personaName,                size = 32.dp,            )            Spacer(modifier = Modifier.size(8.dp))            Column {                Row(verticalAlignment = Alignment.CenterVertically) {                    Text(                        text = personaName,                        style = MaterialTheme.typography.labelMedium,                        color = MaterialTheme.colorScheme.onSurface,                        fontWeight = FontWeight.SemiBold,                    )                    if (item.layer != null) {                        Spacer(modifier = Modifier.size(6.dp))                        LayerBadge(layerName = item.layer)                    }                    if (item.latency != null) {                        Spacer(modifier = Modifier.size(6.dp))                        Text(                            text = item.latency,                            style = MaterialTheme.typography.labelSmall,                            color = MaterialTheme.colorScheme.onSurfaceVariant,                        )                    }                }                Spacer(modifier = Modifier.size(4.dp))                Text(                    text = item.text,                    style = MaterialTheme.typography.bodyLarge,                    color = MaterialTheme.colorScheme.onSurface,                    modifier = Modifier                        .background(                            color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.7f),                            shape = RoundedCornerShape(16.dp, 16.dp, 16.dp, 4.dp),                        )                        .padding(horizontal = 14.dp, vertical = 10.dp),                )            }        }    } else {        // User message — right aligned        Column(            modifier = Modifier.fillMaxWidth(),            horizontalAlignment = Alignment.End,        ) {            Text(                text = item.speaker,                style = MaterialTheme.typography.labelSmall,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )            Spacer(modifier = Modifier.size(4.dp))            Text(                text = item.text,                style = MaterialTheme.typography.bodyLarge,                color = MaterialTheme.colorScheme.onSurface,                modifier = Modifier                    .background(                        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f),                        shape = RoundedCornerShape(16.dp, 16.dp, 4.dp, 16.dp),                    )                    .padding(horizontal = 14.dp, vertical = 10.dp),            )        }    }}@Composableprivate fun StreamingIndicator(    personaName: String,    partial: String,) {    Row(        modifier = Modifier.fillMaxWidth(),        verticalAlignment = Alignment.Top,    ) {        Text(            text = "● ● ● $personaName is thinking...",            style = MaterialTheme.typography.labelMedium,            color = MaterialTheme.colorScheme.primary,        )    }    if (partial.isNotBlank()) {        Spacer(modifier = Modifier.size(4.dp))        Text(            text = partial,            style = MaterialTheme.typography.bodyLarge,            color = MaterialTheme.colorScheme.onSurfaceVariant,        )    }}/** * Input bar — text input + attach + mic + send. * * @param text current input text * @param onTextChange callback when text changes * @param onSendClick callback when send button tapped * @param onMicClick callback when mic button tapped * @param onAttachClick callback when attach button tapped * @param isListening when true, mic button turns red */@Composablefun InputBar(    text: String,    onTextChange: (String) -> Unit,    onSendClick: () -> Unit,    onMicClick: () -> Unit,    onAttachClick: () -> Unit,    isListening: Boolean,    modifier: Modifier = Modifier,) {    Row(        modifier = modifier            .fillMaxWidth()            .background(                color = MaterialTheme.colorScheme.surface.copy(alpha = 0.95f),                shape = RoundedCornerShape(24.dp),            )            .padding(horizontal = 8.dp, vertical = 8.dp),        verticalAlignment = Alignment.CenterVertically,    ) {        CircleIconButton(            icon = Icons.Default.AttachFile,            contentDescription = "Attach",            onClick = onAttachClick,            size = 40.dp,            gradient = false,        )        Spacer(modifier = Modifier.size(8.dp))        // Text field (transparent background, no decoration)        androidx.compose.material3.TextField(            value = text,            onValueChange = onTextChange,            placeholder = {                Text(                    text = "Type a message or use mic...",                    style = MaterialTheme.typography.bodyLarge,                    color = MaterialTheme.colorScheme.onSurfaceVariant,                )            },            modifier = Modifier.weight(1f),            colors = androidx.compose.material3.TextFieldDefaults.colors(                focusedContainerColor = Color.Transparent,                unfocusedContainerColor = Color.Transparent,                disabledContainerColor = Color.Transparent,                focusedIndicatorColor = Color.Transparent,                unfocusedIndicatorColor = Color.Transparent,            ),            textStyle = MaterialTheme.typography.bodyLarge.copy(color = MaterialTheme.colorScheme.onSurface),        )        CircleIconButton(            icon = Icons.Default.Mic,            contentDescription = "Voice input",            onClick = onMicClick,            size = 40.dp,            gradient = false,        )        Spacer(modifier = Modifier.size(4.dp))        val canSend = text.isNotBlank()        CircleIconButton(            icon = Icons.Default.Send,            contentDescription = "Send",            onClick = { if (canSend) onSendClick() },            size = 40.dp,            gradient = true,            enabled = canSend,        )    }}